  const bx0 = stageEnd[3] + 0.45, BW = 0.12, BD = 0.12, lowH = 0.52, gapH = 0.26, topH = 0.52;
  [bx0, bx0 + 0.35].forEach((bx, i) => {
    addSlab(netGroup, bx, 0, BW, lowH, BD, TEAL);
    addSlab(netGroup, bx, lowH + gapH, BW, topH, BD, TEAL);
    for (let k = 0; k < 3; k++)
      netGroup.add(makeDot(V(bx + BW / 2, lowH + 0.065 + k * 0.065, BD / 2 + 0.01), 0.017, 0x333333));
    lbl('k1000' + i, '1000', V(bx + BW / 2, lowH + gapH + topH + 0.22, BD / 2), { fontSize: '11px' });
  });

  /* bottom call-outs (arrows point up-right into the target block) */
  function callout(key, text, tip, dx, dy, tx, ty) {
    netGroup.add(makeArrow(tip.clone().add(V(dx, dy, 0)), tip, 0x000000, 0.13));
    lbl(key, text, tip.clone().add(V(tx, ty, 0)), { rot: -33, fontSize: '11px' });
  }
  callout('conv7', 'Conv 7×7<br>Stride 2', V(OX, 0.06, OD / 2), -0.85, -0.55, -1.75, -0.80);
  callout('maxpool', 'MaxPool', V(stageStart[0], 0.05, STAGE[0].d / 2), -1.05, -0.95, -1.95, -1.22);
  for (let si = 1; si < 4; si++) {
    callout('sub' + si, 'Subsample',
      V(stageStart[si], 0.04, STAGE[si].d / 2), -1.10, -0.68, -2.05, -0.96);
  }
  callout('avgfc', 'AvgPool + FC', V(bx0, 0.05, BD / 2), -1.45, -0.60, -2.45, -0.88);
  callout('softmax', 'Softmax', V(bx0 + 0.35, 0.05, BD / 2), -1.30, -0.95, -2.10, -1.24);
}

/* ── inset panel ─────────────────────────────────────────────────────── */
const CHAIN = [
  { t: 'BN', w: 0.45, c: COL.bn }, { t: 'ReLU', w: 0.60, c: COL.relu }, { t: 'Conv 1×1', w: 1.00, c: COL.white },
  { t: 'BN', w: 0.45, c: COL.bn }, { t: 'ReLU', w: 0.60, c: COL.relu }, { t: 'Conv 3×3', w: 1.00, c: COL.white },
  { t: 'BN', w: 0.45, c: COL.bn }, { t: 'ReLU', w: 0.60, c: COL.relu }, { t: 'Conv 1×1', w: 1.00, c: COL.white }
];
const CY = 5.05, CH = 0.44, CHAIN_X0 = 10.55, CGAP = 0.14;
const PANEL = { x0: 8.55, y0: 4.15, x1: 18.75, y1: 6.45 };
const SKIP_Y = 6.15, JX = 10.16, OPX = 18.05, OPR = 0.13;
let chainBoxes = [], convCenters = [];

function buildInset() {
  CURG = 'inset';
  clearGroup(insetGroup);
  chainBoxes = []; convCenters = [];

  /* panel */
  const shp = roundedRectShape(PANEL.x0, PANEL.y0, PANEL.x1, PANEL.y1, 0.16);
  const fill = new THREE.Mesh(new THREE.ShapeGeometry(shp),
    new THREE.MeshBasicMaterial({ color: COL.panel, side: THREE.DoubleSide }));
  fill.position.z = -0.03; insetGroup.add(fill);
  const pp = shp.getPoints(64).map(p => V(p.x, p.y, -0.02));
  pp.push(pp[0].clone());
  insetGroup.add(makeLine(pp, 0x000000));

  /* cube + equals + entry arrow */
  const cube = makeSlab(0.34, 0.60, 0.60, BLUE);
  cube.position.set(9.02, CY, 0);
  insetGroup.add(cube);
  registerInteractive(cube.userData.mesh, {
    title: 'One ResBlock',
    tooltip: 'The block, abstracted',
    body: 'Each slab in the main diagram is one of these blocks. It equals the BN → ReLU → Conv chain on the right plus an identity skip summed at ⊕.'
  });
  lbl('eq', '=', V(9.62, CY, 0.02), { fontSize: '19px', color: '#2e8b80', bold: true });
  insetGroup.add(makeArrow(V(9.95, CY, 0.02), V(CHAIN_X0, CY, 0.02), 0x000000, 0.11));
  insetGroup.add(makeDot(V(JX, CY, 0.03), 0.035, 0x000000));

  /* chain */
  let x = CHAIN_X0;
  CHAIN.forEach((it, i) => {
    const cx = x + it.w / 2;
    const b = flatBox(cx, CY, it.w, CH, it.c);
    insetGroup.add(b);
    chainBoxes.push({ mesh: b.userData.mesh, base: it.c, x0: x, x1: x + it.w, cx });
    lbl('c' + i, it.t, V(cx, CY, 0.03), { fontSize: '10.5px' });
    if (it.t.indexOf('Conv') === 0) convCenters.push(cx);
    if (i < CHAIN.length - 1) insetGroup.add(makeArrow(V(x + it.w, CY, 0.02), V(x + it.w + CGAP, CY, 0.02), 0x000000, 0.10));
    x += it.w + CGAP;
  });
  const chainEnd = x - CGAP;
  insetGroup.add(makeArrow(V(chainEnd, CY, 0.02), V(OPX - OPR, CY, 0.02), 0x000000, 0.10));

  /* skip connection */
  insetGroup.add(makeLine([V(JX, CY, 0.02), V(JX, SKIP_Y, 0.02), V(OPX, SKIP_Y, 0.02)]));
  insetGroup.add(makeArrow(V(OPX, SKIP_Y, 0.02), V(OPX, CY + OPR, 0.02), 0x000000, 0.11));

  /* circled plus */
  const circ = new THREE.Mesh(new THREE.CircleGeometry(OPR, 32),
    new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide }));
  circ.position.set(OPX, CY, 0.01);
  insetGroup.add(circ);
  opMesh = circ;
  const ring = [];
  for (let i = 0; i <= 48; i++) { const a = i / 48 * Math.PI * 2; ring.push(V(OPX + OPR * Math.cos(a), CY + OPR * Math.sin(a), 0.02)); }
  insetGroup.add(makeLine(ring));
  insetGroup.add(makeLine([V(OPX - OPR * 0.6, CY, 0.03), V(OPX + OPR * 0.6, CY, 0.03)]));
  insetGroup.add(makeLine([V(OPX, CY - OPR * 0.6, 0.03), V(OPX, CY + OPR * 0.6, 0.03)]));

  /* output arrow leaving the panel */
  insetGroup.add(makeArrow(V(OPX + OPR, CY, 0.02), V(19.05, CY, 0.02), 0x000000, 0.12));

  /* channel captions + title */
  lbl('cap0', '', V(convCenters[0], CY - 0.42, 0.03), { fontSize: '9.5px', color: '#20303a' });
  lbl('cap1', '', V(convCenters[1], CY - 0.42, 0.03), { fontSize: '9.5px', color: '#20303a' });
  lbl('cap2', '', V(convCenters[2], CY - 0.42, 0.03), { fontSize: '9.5px', color: '#20303a' });
  lbl('itl', '', V(9.55, PANEL.y1 - 0.22, 0.03), { fontSize: '10px', color: '#333' });

  /* pulses */
  pulseMain = new THREE.Mesh(new THREE.SphereGeometry(0.075, 14, 12),
    new THREE.MeshBasicMaterial({ color: 0xff6a00 }));
  pulseSkip = new THREE.Mesh(new THREE.SphereGeometry(0.075, 14, 12),
    new THREE.MeshBasicMaterial({ color: 0x1f6fb5 }));
  pulseOut = new THREE.Mesh(new THREE.SphereGeometry(0.075, 14, 12),
    new THREE.MeshBasicMaterial({ color: 0x2e8b57 }));
  [pulseMain, pulseSkip, pulseOut].forEach(p => { p.visible = false; p.position.z = 0.06; insetGroup.add(p); });
}

let opMesh = null, pulseMain = null, pulseSkip = null, pulseOut = null;

/* ── stage channel captions ──────────────────────────────────────────── */
let curStage = 0;
function setStageChannels(si) {
  curStage = si;
  const C = STAGE[si].C, B = C / 4;
  lbl('cap0', C + '→' + B, V(convCenters[0], CY - 0.42, 0.03), {});
  lbl('cap1', B + '→' + B, V(convCenters[1], CY - 0.42, 0.03), {});
  lbl('cap2', B + '→' + C, V(convCenters[2], CY - 0.42, 0.03), {});
  lbl('itl', 'Stage ' + (si + 1) + ' · C = ' + C, V(9.55, PANEL.y1 - 0.22, 0.03), {});
  document.getElementById('chanInfo').innerHTML =
    '<b>Stage ' + (si + 1) + ' bottleneck</b><br>Conv 1×1: ' + C + '→' + B +
    ' · Conv 3×3: ' + B + '→' + B + ' · Conv 1×1: ' + B + '→' + C;
}

/* ── build + camera ──────────────────────────────────────────────────── */
let depthVal = 24;
buildNetwork(depthVal);
buildInset();
setStageChannels(0);

function frame(hf) {
  setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0, heightFraction: hf });
}
frame(0.62);
document.getElementById('btnReset').style.display = '';

/* ── view mode ───────────────────────────────────────────────────────── */
let mode = 'full';
function setMode(m) {
  mode = m;
  if (m === 'detail') {
    if (netGroup.parent) scene.remove(netGroup);
    setNetLabelsVisible(false);
    setInsetFontScale(1.9);
    frame(0.72);
  } else {
    if (!netGroup.parent) scene.add(netGroup);
    setNetLabelsVisible(true);
    setInsetFontScale(1.0);
    frame(0.62);
  }
  document.getElementById('btnFull').classList.toggle('active', m === 'full');
  document.getElementById('btnDetail').classList.toggle('active', m === 'detail');
}
document.getElementById('btnFull').onclick = () => setMode('full');
document.getElementById('btnDetail').onclick = () => setMode('detail');

/* ── depth slider ────────────────────────────────────────────────────── */
const depthEl = document.getElementById('depth');
function setDepth(v) {
  depthVal = v;
  depthEl.value = String(v);
  document.getElementById('depthVal').textContent = v;
  buildNetwork(v);
  if (mode === 'full') { setNetLabelsVisible(true); frame(0.62); }
  else { setNetLabelsVisible(false); if (netGroup.parent) scene.remove(netGroup); }
}
depthEl.addEventListener('input', () => setDepth(parseInt(depthEl.value, 10)));

/* ── signal-flow animation ───────────────────────────────────────────── */
function pathLen(pts) {
  let L = 0; const seg = [];
  for (let i = 1; i < pts.length; i++) { const d = pts[i].distanceTo(pts[i - 1]); seg.push(d); L += d; }
  return { seg, L };
}
function pathAt(pts, info, t) {
  let dist = Math.max(0, Math.min(1, t)) * info.L;
  for (let i = 0; i < info.seg.length; i++) {
    if (dist <= info.seg[i] || i === info.seg.length - 1) {
      const f = info.seg[i] > 0 ? dist / info.seg[i] : 0;
      return pts[i].clone().lerp(pts[i + 1], Math.min(1, f));
    }
    dist -= info.seg[i];
  }
  return pts[pts.length - 1].clone();
}
const mainPts = [V(JX, CY, 0.06), V(OPX - OPR, CY, 0.06)];
const skipPts = [V(JX, CY, 0.06), V(JX, SKIP_Y, 0.06), V(OPX, SKIP_Y, 0.06), V(OPX, CY + OPR, 0.06)];
const outPts = [V(OPX + OPR, CY, 0.06), V(19.05, CY, 0.06)];
const mainInfo = pathLen(mainPts), skipInfo = pathLen(skipPts), outInfo = pathLen(outPts);

let flowOn = false, flowT = 0, flowPhase = 0, opFlash = 0;
function highlight(px) {
  chainBoxes.forEach(b => {
    const on = flowOn && px >= b.x0 - 0.02 && px <= b.x1 + 0.02;
    const c = new THREE.Color(b.base);
    if (on) c.lerp(new THREE.Color(0xffe14d), 0.6);
    b.mesh.material.color.copy(c);
  });
}
function flowReset() {
  flowT = 0; flowPhase = 0; opFlash = 0;
  if (pulseMain) { pulseMain.visible = false; pulseSkip.visible = false; pulseOut.visible = false; }
  highlight(-999);
  if (opMesh) opMesh.material.color.set(0xffffff);
}
function flowTick(dt) {
  if (flowPhase === 0) {
    flowT += dt / 3.2;
    pulseMain.visible = true; pulseSkip.visible = true; pulseOut.visible = false;
    pulseMain.position.copy(pathAt(mainPts, mainInfo, flowT));
    pulseSkip.position.copy(pathAt(skipPts, skipInfo, flowT));
    highlight(pulseMain.position.x);
    if (flowT >= 1) { flowPhase = 1; flowT = 0; opFlash = 1; }
  } else if (flowPhase === 1) {
    opFlash -= dt / 0.45;
    const c = new THREE.Color(0xffffff).lerp(new THREE.Color(0xffd23f), Math.max(0, opFlash));
    opMesh.material.color.copy(c);
    pulseMain.visible = false; pulseSkip.visible = false;
    highlight(-999);
    if (opFlash <= 0) { flowPhase = 2; flowT = 0; opMesh.material.color.set(0xffffff); }
  } else {
    flowT += dt / 0.7;
    pulseOut.visible = true;
    pulseOut.position.copy(pathAt(outPts, outInfo, flowT));
    if (flowT >= 1) { pulseOut.visible = false; flowPhase = 0; flowT = 0; }
  }
}
let _lastT = performance.now();
(function loop() {
  requestAnimationFrame(loop);
  const n = performance.now();
  const dt = Math.min(0.05, (n - _lastT) / 1000); _lastT = n;
  if (flowOn) flowTick(dt);
})();

const btnFlow = document.getElementById('btnFlow');
btnFlow.onclick = () => {
  flowOn = !flowOn;
  if (flowOn) { if (mode !== 'detail') setMode('detail'); flowReset(); flowOn = true; btnFlow.textContent = '■ Stop signal trace'; btnFlow.classList.add('active'); }
  else { flowReset(); btnFlow.textContent = '▶ Trace signal through ResBlock'; btnFlow.classList.remove('active'); }
};

/* ── guided tour ─────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'Tensor pipeline', view: 'full', depth: 24, flow: false,
    text: 'Follow the tensors left to right: the 224×224×3 image becomes 112×112×64 after Conv 7×7 stride 2, then four residual stages shrink space and grow channels to 7×7×2048 before AvgPool + FC gives 1000 logits.'
  },
  {
    title: 'Depth is repetition', view: 'full', depth: 36, flow: false,
    text: 'Push the depth slider to 36 blocks: more slabs appear inside each stage and the “36 blocks total” label updates, but every tensor dimension stays exactly the same.'
  },
  {
    title: 'Inside one block', view: 'detail', depth: 36, flow: false,
    text: 'Open the inset: the single cube expands into BN → ReLU → Conv 1×1 → BN → ReLU → Conv 3×3 → BN → ReLU → Conv 1×1, with a skip line arcing over the top.'
  },
  {
    title: 'Two paths, one sum', view: 'detail', depth: 24, flow: true,
    text: 'Play the signal trace: the main path is processed layer by layer while the identity copy runs unchanged along the skip; the ⊕ adds them, so gradients reach earlier layers directly.'
  }
];
let step = 0;
function goToStep(i) {
  step = (i + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  if (s.depth !== depthVal) setDepth(s.depth);
  setMode(s.view);
  flowOn = s.flow;
  flowReset(); flowOn = s.flow;
  btnFlow.textContent = flowOn ? '■ Stop signal trace' : '▶ Trace signal through ResBlock';
  btnFlow.classList.toggle('active', flowOn);
  document.getElementById('stepTitle').textContent = (step + 1) + '. ' + s.title;
  document.getElementById('stepText').textContent = s.text;
}
document.getElementById('btnNext').onclick = () => goToStep(step + 1);
document.getElementById('btnPrev').onclick = () => goToStep(step - 1);
goToStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

