// @FIGURE_CODE_BEGIN
/* ── Element spec (one line per element) ──────────────────────────────────
 input image slab        → BoxGeometry(0.08, 3.0, 3.0), CanvasTexture(candles) on +X face
 '224 × 224 × 3'         → addLabel rot -33° + Line/Cone leader arrow
 conv1 orange slab       → BoxGeometry(0.50, 1.60, 1.60)  #C4693B / #9C4E2B / #D98A5E
 '112 × 112 × 64'        → addLabel rot -33° + leader arrow
 stage-1 ResBlocks (×n)  → BoxGeometry(0.55, 0.90, 0.90)  #A8BFCE/#C6D6DF/#5F7E8F + EdgesGeometry
 stage-2 ResBlocks (×n)  → BoxGeometry(0.80, 0.55, 0.55)
 stage-3 ResBlocks (×n)  → BoxGeometry(1.30, 0.34, 0.34)
 stage-4 ResBlocks (×n)  → BoxGeometry(2.20, 0.20, 0.20)
 logit bars (×2)         → BoxGeometry(0.12, 0.52/0.52, 0.12) teal #B6DFDA + 3 CircleGeometry dots
 stage brackets          → Line (screen plane) + Cone arrows down-left onto each slab top
 'n blocks total'        → addLabel + 2 CircleGeometry dots + dashed Line
 bottom callouts         → Line + Cone arrows up-right, addLabel rot -33°
 inset panel             → Shape(rounded rect) → ShapeGeometry fill + Line border
 inset cube              → BoxGeometry(0.42, 0.72, 0.72)
 inset chain boxes       → PlaneGeometry + EdgesGeometry (BN #E2804F, ReLU #A6DCD2, Conv white)
 inset connectors        → Line + Cone arrows
 skip connection         → polyline Line over the top + Cone arrow into ⊕
 ⊕ node                  → CircleGeometry fill + LineLoop circle + 2 cross Lines
 signal pulses           → SphereGeometry(0.085) travelling main / skip polylines
 bounds padding          → invisible LineSegments reserving space for HTML labels
──────────────────────────────────────────────────────────────────────────── */

const SZ = 0.35355;                       // screen shift per unit of +Z (cabinet oblique)

const COL = {
  front: 0xA8BFCE, top: 0xC6D6DF, side: 0x5F7E8F,
  oFront: 0x9C4E2B, oTop: 0xD98A5E, oSide: 0xC4693B,
  tFront: 0xB6DFDA, tTop: 0xD2EDEA, tSide: 0x7FBDB6,
  bn: 0xE2804F, relu: 0xA6DCD2, white: 0xFFFFFF, panel: 0xBFBFBF
};
const BLUE = { front: COL.front, top: COL.top, side: COL.side };
const ORANGE = { front: COL.oFront, top: COL.oTop, side: COL.oSide };
const TEAL = { front: COL.tFront, top: COL.tTop, side: COL.tSide };

function V(x, y, z) { return new THREE.Vector3(x, y, z === undefined ? 0 : z); }

/* ── primitives ──────────────────────────────────────────────────────── */
function makeSlab(w, h, dd, c, map) {
  const g = new THREE.Group();
  const geo = new THREE.BoxGeometry(w, h, dd);
  const M = (col) => new THREE.MeshBasicMaterial({ color: col, side: THREE.DoubleSide });
  const mats = [
    map ? new THREE.MeshBasicMaterial({ map, side: THREE.DoubleSide }) : M(c.side), // +X
    M(c.side), M(c.top), M(c.side), M(c.front), M(c.front)
  ];
  const mesh = new THREE.Mesh(geo, mats);
  g.add(mesh);
  g.add(new THREE.LineSegments(new THREE.EdgesGeometry(geo),
    new THREE.LineBasicMaterial({ color: 0x000000 })));
  g.userData.mesh = mesh;
  return g;
}
function addSlab(parent, x0, y0, w, h, dd, c, map) {
  const g = makeSlab(w, h, dd, c, map);
  g.position.set(x0 + w / 2, y0 + h / 2, 0);
  parent.add(g);
  return g;
}
function makeLine(pts, color, dashed) {
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: color === undefined ? 0x000000 : color, dashSize: 0.09, gapSize: 0.08 })
    : new THREE.LineBasicMaterial({ color: color === undefined ? 0x000000 : color });
  const l = new THREE.Line(geo, m);
  if (dashed) l.computeLineDistances();
  return l;
}
function makeArrow(a, b, color, head) {
  color = color === undefined ? 0x000000 : color;
  head = head || 0.14;
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) return g;
  dir.normalize();
  const shaftEnd = b.clone().addScaledVector(dir, -head * 0.85);
  g.add(makeLine([a.clone(), shaftEnd], color));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(head * 0.40, head, 12),
    new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
  cone.position.copy(b).addScaledVector(dir, -head / 2);
  cone.quaternion.setFromUnitVectors(V(0, 1, 0), dir);
  g.add(cone);
  return g;
}
function makeDot(p, r, color) {
  const m = new THREE.Mesh(new THREE.CircleGeometry(r || 0.05, 16),
    new THREE.MeshBasicMaterial({ color: color === undefined ? 0x1f4e6b : color, side: THREE.DoubleSide }));
  m.position.copy(p);
  return m;
}
function roundedRectShape(x0, y0, x1, y1, r) {
  const s = new THREE.Shape();
  s.moveTo(x0 + r, y0);
  s.lineTo(x1 - r, y0); s.quadraticCurveTo(x1, y0, x1, y0 + r);
  s.lineTo(x1, y1 - r); s.quadraticCurveTo(x1, y1, x1 - r, y1);
  s.lineTo(x0 + r, y1); s.quadraticCurveTo(x0, y1, x0, y1 - r);
  s.lineTo(x0, y0 + r); s.quadraticCurveTo(x0, y0, x0 + r, y0);
  return s;
}
function flatBox(cx, cy, w, h, color) {
  const g = new THREE.Group();
  const geo = new THREE.PlaneGeometry(w, h);
  const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
  mesh.position.set(cx, cy, 0.004);
  g.add(mesh);
  const e = new THREE.LineSegments(new THREE.EdgesGeometry(geo),
    new THREE.LineBasicMaterial({ color: 0x000000 }));
  e.position.set(cx, cy, 0.008);
  g.add(e);
  g.userData.mesh = mesh;
  return g;
}
function clearGroup(g) {
  while (g.children.length) { const c = g.children.pop(); _disposeObject(c); }
}
function boundsPad(parent, x0, y0, x1, y1) {
