  rg.addColorStop(0, 'rgba(255,190,80,0.85)'); rg.addColorStop(0.35, 'rgba(210,100,25,0.35)');
  rg.addColorStop(1, 'rgba(0,0,0,0)');
  x.fillStyle = rg; x.fillRect(0, 0, 256, 256);
  const xs = [70, 99, 128, 157, 186];
  xs.forEach((cx, i) => {
