    fg.addColorStop(0, '#fff8dc'); fg.addColorStop(0.3, '#ffd070');
    fg.addColorStop(0.65, 'rgba(255,140,30,0.55)'); fg.addColorStop(1, 'rgba(255,100,10,0)');
    x.fillStyle = fg;
