  /* bottom call-outs: arrows point up-right into their target block */
  function callout(key, text, tgt, ax, ay, lx, ly) {
    const tsx = tgt.x + SZ * tgt.z, tsy = tgt.y + SZ * tgt.z;
    netGroup.add(makeArrow(V(tsx + ax, tsy + ay, 0), tgt, 0x000000, 0.15));
    lbl(key, text, V(tsx + lx, tsy + ly, 0), { rot: -33, wu: 0.25 });
  }
  callout('conv7', 'Conv 7×7<br>Stride 2', V(OX, 0.06, OD / 2), -1.05, -0.62, -2.05, -1.02);
  callout('maxpool', 'MaxPool', V(stageStart[0], 0.05, STAGE[0].d / 2), -1.05, -0.95, -1.86, -1.56);
  for (let si = 1; si < 4; si++) {
    callout('sub' + si, 'Subsample', V(stageStart[si], 0.04, STAGE[si].d / 2), -1.15, -0.80, -2.05, -1.22);
  }
  callout('avgfc', 'AvgPool + FC', V(bx0, 0.05, BD / 2), -1.35, -0.62, -2.42, -1.00);
  callout('softmax', 'Softmax', V(bx0 + BSEP, 0.05, BD / 2), -1.25, -1.05, -2.10, -1.50);

  /* reserve space for the HTML labels so the auto-fit never clips them */
  boundsPad(netGroup, -2.35, -2.05, bx0 + BSEP + 0.9, 5.05);
}

/* ── inset panel ─────────────────────────────────────────────────────── */
const CHAIN = [
  { t: 'BN', w: 0.62, c: COL.bn, k: 'bn' }, { t: 'ReLU', w: 0.80, c: COL.relu, k: 'relu' }, { t: 'Conv 1×1', w: 1.32, c: COL.white, k: 'c1' },
  { t: 'BN', w: 0.62, c: COL.bn, k: 'bn' }, { t: 'ReLU', w: 0.80, c: COL.relu, k: 'relu' }, { t: 'Conv 3×3', w: 1.32, c: COL.white, k: 'c3' },
  { t: 'BN', w: 0.62, c: COL.bn, k: 'bn' }, { t: 'ReLU', w: 0.80, c: COL.relu, k: 'relu' }, { t: 'Conv 1×1', w: 1.32, c: COL.white, k: 'c1b' }
];
const CINFO = {
  bn: ['Batch Normalization', 'Normalizes each channel over the mini-batch, then rescales with learned γ, β. Keeps activations well-conditioned so very deep stacks stay trainable.'],
  relu: ['ReLU', 'Element-wise max(0, x) — the non-linearity between convolutions.'],
  c1: ['Conv 1×1 (squeeze)', 'Bottleneck: drops the channel count from C to C/4 so the expensive 3×3 runs on a quarter of the channels.'],
  c3: ['Conv 3×3', 'The only spatial convolution in the block; it runs at the narrow bottleneck width C/4.'],
  c1b: ['Conv 1×1 (expand)', 'Restores the channel count back to C so the result can be added to the identity skip at ⊕.']
};
const CY = 5.62, CH = 0.56, CHAIN_X0 = 9.78, CGAP = 0.20;
const PANEL = { x0: 7.95, y0: 4.25, x1: 20.85, y1: 7.05 };
const SKIP_Y = 6.60, JX = 9.58, OPR = 0.16;
let OPX = 19.9;
let chainBoxes = [], convCenters = [];
let opMesh = null, pulseMain = null, pulseSkip = null, pulseOut = null;

function buildInset() {
  CURG = 'inset';
  clearGroup(insetGroup);
  dropInteractives('inset');
  chainBoxes = []; convCenters = [];

  /* panel */
  const shp = roundedRectShape(PANEL.x0, PANEL.y0, PANEL.x1, PANEL.y1, 0.18);
  const fill = new THREE.Mesh(new THREE.ShapeGeometry(shp),
    new THREE.MeshBasicMaterial({ color: COL.panel, side: THREE.DoubleSide }));
  fill.position.z = -0.03; insetGroup.add(fill);
  const pp = shp.getPoints(64).map(p => V(p.x, p.y, -0.02));
  pp.push(pp[0].clone());
  insetGroup.add(makeLine(pp, 0x000000));

  /* cube + equals + entry arrow */
  const cube = makeSlab(0.42, 0.72, 0.72, BLUE);
  cube.position.set(8.62, CY, 0);
  insetGroup.add(cube);
  cube.userData.mesh.userData.grp = 'inset';
  registerInteractive(cube.userData.mesh, {
    title: 'One ResBlock',
    tooltip: 'The block, abstracted',
    body: 'Every slab in the main diagram is one of these blocks. It equals the BN → ReLU → Conv chain on the right plus an identity skip summed at ⊕, so the layers only have to learn a residual correction.'
  });
  lbl('eq', '=', V(9.24, CY, 0.02), { wu: 0.52, color: '#2e8b80', bold: true, align: 'center' });
  insetGroup.add(makeArrow(V(9.42, CY, 0.02), V(CHAIN_X0, CY, 0.02), 0x000000, 0.13));
  insetGroup.add(makeDot(V(JX, CY, 0.03), 0.042, 0x000000));

  /* chain */
  let x = CHAIN_X0;
  CHAIN.forEach((it, i) => {
    const cx = x + it.w / 2;
    const b = flatBox(cx, CY, it.w, CH, it.c);
    insetGroup.add(b);
    b.userData.mesh.userData.grp = 'inset';
    registerInteractive(b.userData.mesh, {
      title: CINFO[it.k][0], tooltip: it.t, body: CINFO[it.k][1]
    });
    chainBoxes.push({ mesh: b.userData.mesh, base: it.c, x0: x, x1: x + it.w, cx });
    lbl('c' + i, it.t, V(cx, CY, 0.03), { wu: 0.235, maxW: it.w * 0.88, align: 'center' });
    if (it.t.indexOf('Conv') === 0) convCenters.push(cx);
    if (i < CHAIN.length - 1) insetGroup.add(makeArrow(V(x + it.w, CY, 0.02), V(x + it.w + CGAP, CY, 0.02), 0x000000, 0.12));
    x += it.w + CGAP;
  });
  const chainEnd = x - CGAP;
