  for (let i = 0; i <= 48; i++) { const a = i / 48 * Math.PI * 2; ring.push(V(OPX + OPR * Math.cos(a), CY + OPR * Math.sin(a), 0.02)); }
  insetGroup.add(makeLine(ring));
  insetGroup.add(makeLine([V(OPX - OPR * 0.6, CY, 0.03), V(OPX + OPR * 0.6, CY, 0.03)]));
  insetGroup.add(makeLine([V(OPX, CY - OPR * 0.6, 0.03), V(OPX, CY + OPR * 0.6, 0.03)]));

  /* output arrow leaving the panel */
  insetGroup.add(makeArrow(V(OPX + OPR, CY, 0.02), V(PANEL.x1 - 0.18, CY, 0.02), 0x000000, 0.14));

  /* channel captions + title */
  lbl('cap0', '', V(convCenters[0], CY - 0.48, 0.03), { wu: 0.215, color: '#1d2f38', align: 'center' });
  lbl('cap1', '', V(convCenters[1], CY - 0.48, 0.03), { wu: 0.215, color: '#1d2f38', align: 'center' });
  lbl('cap2', '', V(convCenters[2], CY - 0.48, 0.03), { wu: 0.215, color: '#1d2f38', align: 'center' });
  lbl('itl', '', V(8.55, PANEL.y1 - 0.26, 0.03), { wu: 0.235, color: '#2c2c2c', align: 'center' });
  lbl('skl', 'identity skip', V((JX + OPX) / 2, SKIP_Y + 0.20, 0.03), { wu: 0.215, color: '#2b5f83', align: 'center' });

  /* pulses */
  pulseMain = new THREE.Mesh(new THREE.SphereGeometry(0.085, 14, 12),
    new THREE.MeshBasicMaterial({ color: 0xff6a00 }));
  pulseSkip = new THREE.Mesh(new THREE.SphereGeometry(0.085, 14, 12),
    new THREE.MeshBasicMaterial({ color: 0x1f6fb5 }));
  pulseOut = new THREE.Mesh(new THREE.SphereGeometry(0.085, 14, 12),
    new THREE.MeshBasicMaterial({ color: 0x2e8b57 }));
  [pulseMain, pulseSkip, pulseOut].forEach(p => { p.visible = false; p.position.z = 0.06; insetGroup.add(p); });

  /* flow paths depend on OPX, rebuild here */
  mainPts = [V(JX, CY, 0.06), V(OPX - OPR, CY, 0.06)];
  skipPts = [V(JX, CY, 0.06), V(JX, SKIP_Y, 0.06), V(OPX, SKIP_Y, 0.06), V(OPX, CY + OPR, 0.06)];
  outPts = [V(OPX + OPR, CY, 0.06), V(PANEL.x1 - 0.18, CY, 0.06)];
  mainInfo = pathLen(mainPts); skipInfo = pathLen(skipPts); outInfo = pathLen(outPts);
}

/* ── stage channel captions ──────────────────────────────────────────── */
let curStage = 0;
function setStageChannels(si) {
  curStage = si;
  const C = STAGE[si].C, B = C / 4;
  const prev = CURG; CURG = 'inset';
  lbl('cap0', C + ' → ' + B, V(convCenters[0], CY - 0.48, 0.03), {});
  lbl('cap1', B + ' → ' + B, V(convCenters[1], CY - 0.48, 0.03), {});
  lbl('cap2', B + ' → ' + C, V(convCenters[2], CY - 0.48, 0.03), {});
  lbl('itl', 'Stage ' + (si + 1) + ' · C = ' + C, V(8.55, PANEL.y1 - 0.26, 0.03), {});
  CURG = prev;
  document.getElementById('chanInfo').innerHTML =
    '<b>Stage ' + (si + 1) + ' bottleneck</b><br>Conv 1×1: ' + C + '→' + B +
    ' · Conv 3×3: ' + B + '→' + B + ' · Conv 1×1: ' + B + '→' + C;
  fitFonts();
}

/* ── flow path helpers (defined before buildInset uses them) ─────────── */
function pathLen(pts) {
  let L = 0; const seg = [];
  for (let i = 1; i < pts.length; i++) { const dd = pts[i].distanceTo(pts[i - 1]); seg.push(dd); L += dd; }
  return { seg, L };
}
function pathAt(pts, info, t) {
  let dist = Math.max(0, Math.min(1, t)) * info.L;
  for (let i = 0; i < info.seg.length; i++) {
    if (dist <= info.seg[i] || i === info.seg.length - 1) {
      const f = info.seg[i] > 0 ? dist / info.seg[i] : 0;
      return pts[i].clone().lerp(pts[i + 1], Math.min(1, f));
    }
    dist -= info.seg[i];
  }
  return pts[pts.length - 1].clone();
}
let mainPts, skipPts, outPts, mainInfo, skipInfo, outInfo;

/* ── build + camera ──────────────────────────────────────────────────── */
let depthVal = 24;
let mode = 'full';
buildInset();
buildNetwork(depthVal);
setStageChannels(0);

function frame() {
  setCameraView({
    projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0,
    heightFraction: mode === 'detail' ? 0.86 : 0.97
  });
  fitFonts();
}
frame();
document.getElementById('btnReset').style.display = '';

/* ── view mode ───────────────────────────────────────────────────────── */
function setMode(m) {
  mode = m;
  if (m === 'detail') {
    if (netGroup.parent) scene.remove(netGroup);
    setNetLabelsVisible(false);
  } else {
    if (!netGroup.parent) scene.add(netGroup);
    setNetLabelsVisible(true);
  }
  frame();
  document.getElementById('btnFull').classList.toggle('active', m === 'full');
  document.getElementById('btnDetail').classList.toggle('active', m === 'detail');
}
document.getElementById('btnFull').onclick = () => setMode('full');
document.getElementById('btnDetail').onclick = () => setMode('detail');

/* ── depth slider ────────────────────────────────────────────────────── */
const depthEl = document.getElementById('depth');
function setDepth(v) {
  depthVal = v;
  depthEl.value = String(v);
  document.getElementById('depthVal').textContent = v;
  buildNetwork(v);
  if (mode === 'full') { if (!netGroup.parent) scene.add(netGroup); setNetLabelsVisible(true); }
  else { setNetLabelsVisible(false); if (netGroup.parent) scene.remove(netGroup); }
  frame();
}
depthEl.addEventListener('input', () => setDepth(parseInt(depthEl.value, 10)));

/* ── signal-flow animation ───────────────────────────────────────────── */
let flowOn = false, flowT = 0, flowPhase = 0, opFlash = 0;
function highlight(px) {
