const LBL = {}, LBLG = {};
let CURG = 'net';
function plainLen(t) {
  return String(t).split(/<br\s*\/?>/i)
    .map(s => s.replace(/<[^>]*>/g, '').length)
    .reduce((a, b) => Math.max(a, b), 1);
}
function lbl(key, text, pos, opt) {
  opt = opt || {};
  const inner = '<span style="display:inline-block;line-height:1.22;text-align:' +
    (opt.align || 'left') + ';' + (opt.rot ? 'transform:rotate(' + opt.rot + 'deg);' : '') + '">' + text + '</span>';
  let e = LBL[key];
  if (!e) {
    e = LBL[key] = addLabel(inner, pos, { color: opt.color, bold: opt.bold, offset: opt.offset });
    LBLG[key] = CURG;
  } else {
    e.div.innerHTML = inner;
    e.pos.copy(pos);
    if (opt.offset) e.offset = opt.offset;
    if (opt.color) e.div.style.color = opt.color;
  }
  e.wu = opt.wu !== undefined ? opt.wu : (e.wu !== undefined ? e.wu : 0.24);
  e.maxW = opt.maxW !== undefined ? opt.maxW : e.maxW;
  e.tlen = plainLen(text);
  return e;
}
function fitFonts() {
  const H = canvas.clientHeight || 600;
  const ppu = H * (_labelZoomRef || 1) / (2 * d);
  Object.keys(LBL).forEach(k => {
    const e = LBL[k];
    let px = (e.wu || 0.24) * ppu;
    if (e.maxW) px = Math.min(px, (e.maxW * ppu) / (0.56 * Math.max(1, e.tlen)));
    px = Math.max(6.5, Math.min(34, px));
    e.div.style.fontSize = px.toFixed(1) + 'px';
  });
}
function setNetLabelsVisible(v) {
  Object.keys(LBL).forEach(k => {
    if (LBLG[k] === 'net') LBL[k].div.style.visibility = v ? '' : 'hidden';
  });
}

/* ── groups ──────────────────────────────────────────────────────────── */
const netGroup = new THREE.Group();
const insetGroup = new THREE.Group();
scene.add(netGroup); scene.add(insetGroup);

/* ── network layout / build ──────────────────────────────────────────── */
const STAGE = [
  { w: 0.55, h: 0.90, d: 0.90, dim: '56 × 56 × 256(64)', C: 256, tight: 0.10, sep: 0.35, gap: 1.35 },
  { w: 0.80, h: 0.55, d: 0.55, dim: '28 × 28 × 512(128)', C: 512, tight: 0.12, sep: 0.30, gap: 1.35 },
  { w: 1.30, h: 0.34, d: 0.34, dim: '14 × 14 × 1024(256)', C: 1024, tight: 0.12, sep: 0.14, gap: 1.00 },
  { w: 2.20, h: 0.20, d: 0.20, dim: '7 × 7 × 2048(512)', C: 2048, tight: 0.10, sep: 0.10, gap: 0.60 }
];
const COUNTS = { 12: [2, 1, 1, 2], 24: [4, 2, 2, 3], 36: [5, 3, 3, 4] };

function buildNetwork(depth) {
  CURG = 'net';
  clearGroup(netGroup);
  dropInteractives('net');
  const counts = COUNTS[depth] || COUNTS[24];

  /* input image (photo on the big +X parallelogram face) */
  const IW = 0.08, IH = 3.0, ID = 3.0;
  addSlab(netGroup, 0, 0, IW, IH, ID, { front: 0x2b1f15, top: 0x40301f, side: 0x241a12 }, CANDLE_TEX);
  netGroup.add(makeArrow(V(1.70, 4.28, 0), V(0.80, 3.55, 0), 0x000000, 0.15));
  lbl('dim0', '224 × 224 × 3', V(2.62, 4.72, 0), { rot: -33, wu: 0.25 });

  /* first conv (orange) */
  const OX = 0.42, OW = 0.50, OH = 1.60, OD = 1.60;
  addSlab(netGroup, OX, 0, OW, OH, OD, ORANGE);
  netGroup.add(makeArrow(V(2.32, 2.90, 0), V(0.92, 2.02, 0), 0x000000, 0.15));
  lbl('dim1', '112 × 112 × 64', V(3.28, 3.34, 0), { rot: -33, wu: 0.25 });

  /* stages */
  let x = OX + OW + 0.45;
  const stageStart = [], stageEnd = [];
  for (let si = 0; si < 4; si++) {
    const s = STAGE[si], n = counts[si];
    const xs = [];
    let cx = x;
    for (let i = 0; i < n; i++) {
      xs.push(cx);
      cx += s.w + (i === n - 2 ? s.sep : s.tight);
    }
    const endX = xs[n - 1] + s.w;
    stageStart.push(xs[0]); stageEnd.push(endX);

    xs.forEach((bx) => {
      const g = addSlab(netGroup, bx, 0, s.w, s.h, s.d, BLUE);
      g.userData.mesh.userData.grp = 'net';
      registerInteractive(g.userData.mesh, {
        title: 'Stage ' + (si + 1) + ' ResBlock — ' + s.dim,
        tooltip: 'ResBlock ' + s.dim + ' (click)',
        body: 'Output tensor ' + s.dim.replace(/\(.*\)/, '') + 'with bottleneck width ' + (s.C / 4) + '. ' +
          'Inside: Conv 1×1 squeezes ' + s.C + '→' + (s.C / 4) + ', Conv 3×3 works at ' + (s.C / 4) +
          ', Conv 1×1 expands ' + (s.C / 4) + '→' + s.C + ', then the identity skip is added at ⊕.',
        onClick: () => { setStageChannels(si); setMode('detail'); }
      });
    });

    /* bracket above the stage, arrows down-left onto each slab top */
    const topScr = s.h + s.d * SZ;
    const by = topScr + 0.72;
    const bxA = xs[0] + s.w * 0.35;
    const bxB = endX + s.d * SZ + 0.50;
    netGroup.add(makeLine([V(bxA, by, 0), V(bxB, by, 0)]));
    xs.forEach(bx => {
      const startX = Math.min(bxB - 0.04, bx + s.w * 0.5 + s.d * SZ + 0.55);
      netGroup.add(makeArrow(V(startX, by, 0), V(bx + s.w * 0.5, s.h + 0.02, s.d * 0.5), 0x000000, 0.14));
    });
    lbl('st' + si, 'ResBlock<br>' + s.dim, V(bxA + 0.78, by + 0.60, 0), { rot: -33, wu: 0.25 });

    x = endX + s.gap;
  }

  /* 'n blocks total' between stage 1-2 and 2-3 */
  [[0, 1, 'bt0'], [1, 2, 'bt1']].forEach(t => {
    const gx = (stageEnd[t[0]] + stageStart[t[1]]) / 2;
    const hh = Math.min(STAGE[t[0]].h, STAGE[t[1]].h);
    lbl(t[2], depth + ' blocks<br>total', V(gx, 0.62, 0), { wu: 0.25, color: '#2b5f83', align: 'center' });
    netGroup.add(makeDot(V(gx - 0.56, 0.30, 0.02), 0.048, 0x2b5f83));
    netGroup.add(makeDot(V(gx + 0.56, 0.30, 0.02), 0.048, 0x2b5f83));
    netGroup.add(makeLine([V(gx - 0.45, hh + 0.28, 0), V(gx + 0.45, hh + 0.28, 0)], 0x000000, true));
  });

  /* logit bars */
  const bx0 = stageEnd[3] + 0.55, BW = 0.12, BD = 0.12, lowH = 0.52, gapH = 0.26, topH = 0.52;
  const BSEP = 0.75;
  [bx0, bx0 + BSEP].forEach((bx, i) => {
    addSlab(netGroup, bx, 0, BW, lowH, BD, TEAL);
    addSlab(netGroup, bx, lowH + gapH, BW, topH, BD, TEAL);
    for (let k = 0; k < 3; k++)
      netGroup.add(makeDot(V(bx + BW / 2, lowH + 0.07 + k * 0.065, BD / 2 + 0.01), 0.018, 0x333333));
    lbl('k1000' + i, '1000', V(bx + BW / 2 + (i ? 0.10 : -0.10), lowH + gapH + topH + 0.26, BD / 2),
      { wu: 0.25, align: 'center' });
  });

  /* bottom call-outs: arrows point up-right into their target block */
  function callout(key, text, tgt, ax, ay, lx, ly) {
    const tsx = tgt.x + SZ * tgt.z, tsy = tgt.y + SZ * tgt.z;
    netGroup.add(makeArrow(V(tsx + ax, tsy + ay, 0), tgt, 0x000000, 0.15));
    lbl(key, text, V(tsx + lx, tsy + ly, 0), { rot: -33, wu: 0.25 });
  }
  callout('conv7', 'Conv 7×7<br>Stride 2', V(OX, 0.06, OD / 2), -1.05, -0.62, -2.05, -1.02);
  callout('maxpool', 'MaxPool', V(stageStart[0], 0.05, STAGE[0].d / 2), -1.05, -0.95, -1.86, -1.56);
  for (let si = 1; si < 4; si++) {
    callout('sub' + si, 'Subsample', V(stageStart[si], 0.04, STAGE[si].d / 2), -1.15, -0.80, -2.05, -1.22);
  }
  callout('avgfc', 'AvgPool + FC', V(bx0, 0.05, BD / 2), -1.35, -0.62, -2.42, -1.00);
  callout('softmax', 'Softmax', V(bx0 + BSEP, 0.05, BD / 2), -1.25, -1.05, -2.10, -1.50);

  /* reserve space for the HTML labels so the auto-fit never clips them */
  boundsPad(netGroup, -2.35, -2.05, bx0 + BSEP + 0.9, 5.05);
}

/* ── inset panel ─────────────────────────────────────────────────────── */
const CHAIN = [
  { t: 'BN', w: 0.62, c: COL.bn, k: 'bn' }, { t: 'ReLU', w: 0.80, c: COL.relu, k: 'relu' }, { t: 'Conv 1×1', w: 1.32, c: COL.white, k: 'c1' },
  { t: 'BN', w: 0.62, c: COL.bn, k: 'bn' }, { t: 'ReLU', w: 0.80, c: COL.relu, k: 'relu' }, { t: 'Conv 3×3', w: 1.32, c: COL.white, k: 'c3' },
  { t: 'BN', w: 0.62, c: COL.bn, k: 'bn' }, { t: 'ReLU', w: 0.80, c: COL.relu, k: 'relu' }, { t: 'Conv 1×1', w: 1.32, c: COL.white, k: 'c1b' }
];
const CINFO = {
  bn: ['Batch Normalization', 'Normalizes each channel over the mini-batch, then rescales with learned γ, β. Keeps activations well-conditioned so very deep stacks stay trainable.'],
  relu: ['ReLU', 'Element-wise max(0, x) — the non-linearity between convolutions.'],
  c1: ['Conv 1×1 (squeeze)', 'Bottleneck: drops the channel count from C to C/4 so the expensive 3×3 runs on a quarter of the channels.'],
  c3: ['Conv 3×3', 'The only spatial convolution in the block; it runs at the narrow bottleneck width C/4.'],
  c1b: ['Conv 1×1 (expand)', 'Restores the channel count back to C so the result can be added to the identity skip at ⊕.']
};
const CY = 5.62, CH = 0.56, CHAIN_X0 = 9.78, CGAP = 0.20;
const PANEL = { x0: 7.95, y0: 4.25, x1: 20.85, y1: 7.05 };
const SKIP_Y = 6.60, JX = 9.58, OPR = 0.16;
let OPX = 19.9;
let chainBoxes = [], convCenters = [];
let opMesh = null, pulseMain = null, pulseSkip = null, pulseOut = null;

function buildInset() {
  CURG = 'inset';
  clearGroup(insetGroup);
  dropInteractives('inset');
  chainBoxes = []; convCenters = [];

  /* panel */
  const shp = roundedRectShape(PANEL.x0, PANEL.y0, PANEL.x1, PANEL.y1, 0.18);
  const fill = new THREE.Mesh(new THREE.ShapeGeometry(shp),
    new THREE.MeshBasicMaterial({ color: COL.panel, side: THREE.DoubleSide }));
  fill.position.z = -0.03; insetGroup.add(fill);
  const pp = shp.getPoints(64).map(p => V(p.x, p.y, -0.02));
  pp.push(pp[0].clone());
  insetGroup.add(makeLine(pp, 0x000000));

  /* cube + equals + entry arrow */
  const cube = makeSlab(0.42, 0.72, 0.72, BLUE);
  cube.position.set(8.62, CY, 0);
  insetGroup.add(cube);
  cube.userData.mesh.userData.grp = 'inset';
  registerInteractive(cube.userData.mesh, {
    title: 'One ResBlock',
    tooltip: 'The block, abstracted',
    body: 'Every slab in the main diagram is one of these blocks. It equals the BN → ReLU → Conv chain on the right plus an identity skip summed at ⊕, so the layers only have to learn a residual correction.'
  });
  lbl('eq', '=', V(9.24, CY, 0.02), { wu: 0.52, color: '#2e8b80', bold: true, align: 'center' });
  insetGroup.add(makeArrow(V(9.42, CY, 0.02), V(CHAIN_X0, CY, 0.02), 0x000000, 0.13));
  insetGroup.add(makeDot(V(JX, CY, 0.03), 0.042, 0x000000));

  /* chain */
  let x = CHAIN_X0;
  CHAIN.forEach((it, i) => {
    const cx = x + it.w / 2;
    const b = flatBox(cx, CY, it.w, CH, it.c);
    insetGroup.add(b);
    b.userData.mesh.userData.grp = 'inset';
    registerInteractive(b.userData.mesh, {
      title: CINFO[it.k][0], tooltip: it.t, body: CINFO[it.k][1]
    });
    chainBoxes.push({ mesh: b.userData.mesh, base: it.c, x0: x, x1: x + it.w, cx });
    lbl('c' + i, it.t, V(cx, CY, 0.03), { wu: 0.235, maxW: it.w * 0.88, align: 'center' });
    if (it.t.indexOf('Conv') === 0) convCenters.push(cx);
    if (i < CHAIN.length - 1) insetGroup.add(makeArrow(V(x + it.w, CY, 0.02), V(x + it.w + CGAP, CY, 0.02), 0x000000, 0.12));
    x += it.w + CGAP;
  });
  const chainEnd = x - CGAP;
  OPX = chainEnd + 0.33;
  insetGroup.add(makeArrow(V(chainEnd, CY, 0.02), V(OPX - OPR, CY, 0.02), 0x000000, 0.12));

  /* skip connection */
  insetGroup.add(makeLine([V(JX, CY, 0.02), V(JX, SKIP_Y, 0.02), V(OPX, SKIP_Y, 0.02)]));
  insetGroup.add(makeArrow(V(OPX, SKIP_Y, 0.02), V(OPX, CY + OPR, 0.02), 0x000000, 0.13));

  /* circled plus */
  const circ = new THREE.Mesh(new THREE.CircleGeometry(OPR, 32),
    new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide }));
  circ.position.set(OPX, CY, 0.01);
  insetGroup.add(circ);
  opMesh = circ;
  circ.userData.grp = 'inset';
  registerInteractive(circ, {
    title: '⊕ element-wise sum',
    tooltip: 'Residual addition',
    body: 'output = F(x) + x. Because the identity term passes straight through, gradients reach earlier layers unattenuated — the reason 50–150 layer networks train at all.'
  });
  const ring = [];
  for (let i = 0; i <= 48; i++) { const a = i / 48 * Math.PI * 2; ring.push(V(OPX + OPR * Math.cos(a), CY + OPR * Math.sin(a), 0.02)); }
  insetGroup.add(makeLine(ring));
  insetGroup.add(makeLine([V(OPX - OPR * 0.6, CY, 0.03), V(OPX + OPR * 0.6, CY, 0.03)]));
  insetGroup.add(makeLine([V(OPX, CY - OPR * 0.6, 0.03), V(OPX, CY + OPR * 0.6, 0.03)]));

  /* output arrow leaving the panel */
  insetGroup.add(makeArrow(V(OPX + OPR, CY, 0.02), V(PANEL.x1 - 0.18, CY, 0.02), 0x000000, 0.14));

  /* channel captions + title */
  lbl('cap0', '', V(convCenters[0], CY - 0.48, 0.03), { wu: 0.215, color: '#1d2f38', align: 'center' });
  lbl('cap1', '', V(convCenters[1], CY - 0.48, 0.03), { wu: 0.215, color: '#1d2f38', align: 'center' });
  lbl('cap2', '', V(convCenters[2], CY - 0.48, 0.03), { wu: 0.215, color: '#1d2f38', align: 'center' });
  lbl('itl', '', V(8.55, PANEL.y1 - 0.26, 0.03), { wu: 0.235, color: '#2c2c2c', align: 'center' });
  lbl('skl', 'identity skip', V((JX + OPX) / 2, SKIP_Y + 0.20, 0.03), { wu: 0.215, color: '#2b5f83', align: 'center' });

  /* pulses */
  pulseMain = new THREE.Mesh(new THREE.SphereGeometry(0.085, 14, 12),
    new THREE.MeshBasicMaterial({ color: 0xff6a00 }));
  pulseSkip = new THREE.Mesh(new THREE.SphereGeometry(0.085, 14, 12),
    new THREE.MeshBasicMaterial({ color: 0x1f6fb5 }));
  pulseOut = new THREE.Mesh(new THREE.SphereGeometry(0.085, 14, 12),
    new THREE.MeshBasicMaterial({ color: 0x2e8b57 }));
  [pulseMain, pulseSkip, pulseOut].forEach(p => { p.visible = false; p.position.z = 0.06; insetGroup.add(p); });

  /* flow paths depend on OPX, rebuild here */
  mainPts = [V(JX, CY, 0.06), V(OPX - OPR, CY, 0.06)];
  skipPts = [V(JX, CY, 0.06), V(JX, SKIP_Y, 0.06), V(OPX, SKIP_Y, 0.06), V(OPX, CY + OPR, 0.06)];
  outPts = [V(OPX + OPR, CY, 0.06), V(PANEL.x1 - 0.18, CY, 0.06)];
  mainInfo = pathLen(mainPts); skipInfo = pathLen(skipPts); outInfo = pathLen(outPts);
}

/* ── stage channel captions ──────────────────────────────────────────── */
let curStage = 0;
function setStageChannels(si) {
  curStage = si;
  const C = STAGE[si].C, B = C / 4;
  const prev = CURG; CURG = 'inset';
  lbl('cap0', C + ' → ' + B, V(convCenters[0], CY - 0.48, 0.03), {});
  lbl('cap1', B + ' → ' + B, V(convCenters[1], CY - 0.48, 0.03), {});
  lbl('cap2', B + ' → ' + C, V(convCenters[2], CY - 0.48, 0.03), {});
  lbl('itl', 'Stage ' + (si + 1) + ' · C = ' + C, V(8.55, PANEL.y1 - 0.26, 0.03), {});
  CURG = prev;
  document.getElementById('chanInfo').innerHTML =
    '<b>Stage ' + (si + 1) + ' bottleneck</b><br>Conv 1×1: ' + C + '→' + B +
    ' · Conv 3×3: ' + B + '→' + B + ' · Conv 1×1: ' + B + '→' + C;
  fitFonts();
}

/* ── flow path helpers (defined before buildInset uses them) ─────────── */
function pathLen(pts) {
  let L = 0; const seg = [];
  for (let i = 1; i < pts.length; i++) { const dd = pts[i].distanceTo(pts[i - 1]); seg.push(dd); L += dd; }
  return { seg, L };
}
function pathAt(pts, info, t) {
  let dist = Math.max(0, Math.min(1, t)) * info.L;
  for (let i = 0; i < info.seg.length; i++) {
    if (dist <= info.seg[i] || i === info.seg.length - 1) {
      const f = info.seg[i] > 0 ? dist / info.seg[i] : 0;
      return pts[i].clone().lerp(pts[i + 1], Math.min(1, f));
    }
    dist -= info.seg[i];
  }
  return pts[pts.length - 1].clone();
}
let mainPts, skipPts, outPts, mainInfo, skipInfo, outInfo;

/* ── build + camera ──────────────────────────────────────────────────── */
let depthVal = 24;
let mode = 'full';
buildInset();
buildNetwork(depthVal);
setStageChannels(0);

function frame() {
  setCameraView({
    projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0,
    heightFraction: mode === 'detail' ? 0.86 : 0.97
  });
  fitFonts();
}
frame();
document.getElementById('btnReset').style.display = '';

/* ── view mode ───────────────────────────────────────────────────────── */
function setMode(m) {
  mode = m;
  if (m === 'detail') {
    if (netGroup.parent) scene.remove(netGroup);
    setNetLabelsVisible(false);
  } else {
    if (!netGroup.parent) scene.add(netGroup);
    setNetLabelsVisible(true);
  }
  frame();
  document.getElementById('btnFull').classList.toggle('active', m === 'full');
  document.getElementById('btnDetail').classList.toggle('active', m === 'detail');
}
document.getElementById('btnFull').onclick = () => setMode('full');
document.getElementById('btnDetail').onclick = () => setMode('detail');

/* ── depth slider ────────────────────────────────────────────────────── */
const depthEl = document.getElementById('depth');
function setDepth(v) {
  depthVal = v;
  depthEl.value = String(v);
  document.getElementById('depthVal').textContent = v;
  buildNetwork(v);
  if (mode === 'full') { if (!netGroup.parent) scene.add(netGroup); setNetLabelsVisible(true); }
  else { setNetLabelsVisible(false); if (netGroup.parent) scene.remove(netGroup); }
  frame();
}
depthEl.addEventListener('input', () => setDepth(parseInt(depthEl.value, 10)));

/* ── signal-flow animation ───────────────────────────────────────────── */
let flowOn = false, flowT = 0, flowPhase = 0, opFlash = 0;
function highlight(px) {
  chainBoxes.forEach(b => {
    const on = flowOn && px >= b.x0 - 0.02 && px <= b.x1 + 0.02;
    const c = new THREE.Color(b.base);
    if (on) c.lerp(new THREE.Color(0xffe14d), 0.6);
    b.mesh.material.color.copy(c);
  });
}
function flowReset() {
  flowT = 0; flowPhase = 0; opFlash = 0;
  if (pulseMain) { pulseMain.visible = false; pulseSkip.visible = false; pulseOut.visible = false; }
  highlight(-999);
  if (opMesh) opMesh.material.color.set(0xffffff);
}
function flowTick(dt) {
  if (flowPhase === 0) {
    flowT += dt / 3.2;
    pulseMain.visible = true; pulseSkip.visible = true; pulseOut.visible = false;
    pulseMain.position.copy(pathAt(mainPts, mainInfo, flowT));
    pulseSkip.position.copy(pathAt(skipPts, skipInfo, flowT));
    highlight(pulseMain.position.x);
    if (flowT >= 1) { flowPhase = 1; flowT = 0; opFlash = 1; }
  } else if (flowPhase === 1) {
    opFlash -= dt / 0.45;
    const c = new THREE.Color(0xffffff).lerp(new THREE.Color(0xffd23f), Math.max(0, opFlash));
    opMesh.material.color.copy(c);
    pulseMain.visible = false; pulseSkip.visible = false;
    highlight(-999);
    if (opFlash <= 0) { flowPhase = 2; flowT = 0; opMesh.material.color.set(0xffffff); }
  } else {
    flowT += dt / 0.7;
    pulseOut.visible = true;
    pulseOut.position.copy(pathAt(outPts, outInfo, flowT));
    if (flowT >= 1) { pulseOut.visible = false; flowPhase = 0; flowT = 0; }
  }
}

let _lastT = performance.now(), _lastH = 0, _lastRef = 0;
(function loop() {
  requestAnimationFrame(loop);
  const n = performance.now();
  const dt = Math.min(0.05, (n - _lastT) / 1000); _lastT = n;
  if (flowOn) flowTick(dt);
  if (canvas.clientHeight !== _lastH || _labelZoomRef !== _lastRef) {
    _lastH = canvas.clientHeight; _lastRef = _labelZoomRef; fitFonts();
  }
})();

const btnFlow = document.getElementById('btnFlow');
btnFlow.onclick = () => {
  flowOn = !flowOn;
  if (flowOn) {
    if (mode !== 'detail') setMode('detail');
    flowReset(); flowOn = true;
    btnFlow.textContent = '■ Stop signal trace'; btnFlow.classList.add('active');
  } else {
    flowReset();
    btnFlow.textContent = '▶ Trace signal through ResBlock'; btnFlow.classList.remove('active');
  }
};

/* ── guided tour ─────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'Tensor pipeline', view: 'full', depth: 24, flow: false,
