 signal pulses           → SphereGeometry travelling main / skip / output polylines
 bounds padding          → invisible LineSegments reserving space for HTML labels
──────────────────────────────────────────────────────────────────────────── */

const SZ = 0.35355;                       // screen shift per unit of +Z (cabinet oblique)

const COL = {
  front: 0xA8BFCE, top: 0xC6D6DF, side: 0x5F7E8F,
  oFront: 0x9C4E2B, oTop: 0xD98A5E, oSide: 0xC4693B,
  tFront: 0xB6DFDA, tTop: 0xD2EDEA, tSide: 0x7FBDB6,
  bn: 0xE2804F, relu: 0xA6DCD2, white: 0xFFFFFF, panel: 0xBFBFBF
};
const BLUE = { front: COL.front, top: COL.top, side: COL.side };
const ORANGE = { front: COL.oFront, top: COL.oTop, side: COL.oSide };
const TEAL = { front: COL.tFront, top: COL.tTop, side: COL.tSide };

function V(x, y, z) { return new THREE.Vector3(x, y, z === undefined ? 0 : z); }

/* ── primitives ──────────────────────────────────────────────────────── */
function makeSlab(w, h, dd, c, map) {
  const g = new THREE.Group();
  const geo = new THREE.BoxGeometry(w, h, dd);
  const M = (col) => new THREE.MeshBasicMaterial({ color: col, side: THREE.DoubleSide });
  const mats = [
    map ? new THREE.MeshBasicMaterial({ map, side: THREE.DoubleSide }) : M(c.side), // +X
    M(c.side), M(c.top), M(c.side), M(c.front), M(c.front)
  ];
  const mesh = new THREE.Mesh(geo, mats);
  g.add(mesh);
  g.add(new THREE.LineSegments(new THREE.EdgesGeometry(geo),
    new THREE.LineBasicMaterial({ color: 0x000000 })));
