  return g;
}
function addSlab(parent, x0, y0, w, h, dd, c, map) {
  const g = makeSlab(w, h, dd, c, map);
  g.position.set(x0 + w / 2, y0 + h / 2, 0);
  parent.add(g);
  return g;
}
function makeLine(pts, color, dashed) {
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: color === undefined ? 0x000000 : color, dashSize: 0.10, gapSize: 0.09 })
    : new THREE.LineBasicMaterial({ color: color === undefined ? 0x000000 : color });
  const l = new THREE.Line(geo, m);
  if (dashed) l.computeLineDistances();
  return l;
}
function makeArrow(a, b, color, head) {
  color = color === undefined ? 0x000000 : color;
  head = head || 0.14;
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) return g;
  dir.normalize();
  const shaftEnd = b.clone().addScaledVector(dir, -head * 0.85);
  g.add(makeLine([a.clone(), shaftEnd], color));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(head * 0.40, head, 12),
    new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
  cone.position.copy(b).addScaledVector(dir, -head / 2);
  cone.quaternion.setFromUnitVectors(V(0, 1, 0), dir);
  g.add(cone);
  return g;
}
function makeDot(p, r, color) {
  const m = new THREE.Mesh(new THREE.CircleGeometry(r || 0.05, 16),
    new THREE.MeshBasicMaterial({ color: color === undefined ? 0x1f4e6b : color, side: THREE.DoubleSide }));
  m.position.copy(p);
  return m;
}
function roundedRectShape(x0, y0, x1, y1, r) {
  const s = new THREE.Shape();
  s.moveTo(x0 + r, y0);
  s.lineTo(x1 - r, y0); s.quadraticCurveTo(x1, y0, x1, y0 + r);
  s.lineTo(x1, y1 - r); s.quadraticCurveTo(x1, y1, x1 - r, y1);
  s.lineTo(x0 + r, y1); s.quadraticCurveTo(x0, y1, x0, y1 - r);
  s.lineTo(x0, y0 + r); s.quadraticCurveTo(x0, y0, x0 + r, y0);
  return s;
}
function flatBox(cx, cy, w, h, color) {
  const g = new THREE.Group();
  const geo = new THREE.PlaneGeometry(w, h);
  const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
  mesh.position.set(cx, cy, 0.004);
  g.add(mesh);
  const e = new THREE.LineSegments(new THREE.EdgesGeometry(geo),
    new THREE.LineBasicMaterial({ color: 0x000000 }));
  e.position.set(cx, cy, 0.008);
  g.add(e);
  g.userData.mesh = mesh;
  return g;
}
function clearGroup(g) {
  while (g.children.length) { const c = g.children.pop(); _disposeObject(c); }
}
function boundsPad(parent, x0, y0, x1, y1) {
  const geo = new THREE.BufferGeometry().setFromPoints([V(x0, y0, 0), V(x1, y1, 0)]);
  const l = new THREE.LineSegments(geo, new THREE.LineBasicMaterial({ color: 0xffffff }));
  l.visible = false;
  parent.add(l);
  return l;
}
function dropInteractives(tag) {
  for (let i = _interactiveObjects.length - 1; i >= 0; i--) {
    const o = _interactiveObjects[i].object;
    if (o && o.userData && o.userData.grp === tag) _interactiveObjects.splice(i, 1);
  }
}

/* ── candle photo texture ────────────────────────────────────────────── */
function candleTexture() {
  const cv = document.createElement('canvas'); cv.width = 256; cv.height = 256;
  const x = cv.getContext('2d');
  const g = x.createLinearGradient(0, 0, 0, 256);
  g.addColorStop(0, '#120b05'); g.addColorStop(0.42, '#54280a'); g.addColorStop(0.72, '#1b1008'); g.addColorStop(1, '#070504');
  x.fillStyle = g; x.fillRect(0, 0, 256, 256);
  const rg = x.createRadialGradient(128, 110, 6, 128, 110, 130);
  rg.addColorStop(0, 'rgba(255,190,80,0.85)'); rg.addColorStop(0.35, 'rgba(210,100,25,0.35)');
  rg.addColorStop(1, 'rgba(0,0,0,0)');
  x.fillStyle = rg; x.fillRect(0, 0, 256, 256);
  const xs = [70, 99, 128, 157, 186];
  xs.forEach((cx, i) => {
    const top = 86 + (i % 2 ? 9 : 0);
    const fg = x.createRadialGradient(cx, top, 1, cx, top, 18);
    fg.addColorStop(0, '#fff8dc'); fg.addColorStop(0.3, '#ffd070');
    fg.addColorStop(0.65, 'rgba(255,140,30,0.55)'); fg.addColorStop(1, 'rgba(255,100,10,0)');
    x.fillStyle = fg;
    x.beginPath(); x.ellipse(cx, top, 9, 19, 0, 0, Math.PI * 2); x.fill();
    const wg = x.createLinearGradient(cx - 8, 0, cx + 8, 0);
    wg.addColorStop(0, 'rgba(110,55,18,0.75)'); wg.addColorStop(0.45, 'rgba(226,158,88,0.8)');
    wg.addColorStop(1, 'rgba(80,40,14,0.75)');
    x.fillStyle = wg; x.fillRect(cx - 6, top + 15, 12, 74);
  });
  x.fillStyle = 'rgba(220,220,220,0.55)'; x.font = 'bold 9px sans-serif';
  x.fillText('IMAGENET', 14, 242);
  return new THREE.CanvasTexture(cv);
}
const CANDLE_TEX = candleTexture();

/* ── label registry (font size derived from world units → pixels) ─────── */
const LBL = {}, LBLG = {};
let CURG = 'net';
function plainLen(t) {
  return String(t).split(/<br\s*\/?>/i)
    .map(s => s.replace(/<[^>]*>/g, '').length)
    .reduce((a, b) => Math.max(a, b), 1);
}
function lbl(key, text, pos, opt) {
  opt = opt || {};
  const inner = '<span style="display:inline-block;line-height:1.20;text-align:' +
    (opt.align || 'left') + ';' + (opt.rot ? 'transform:rotate(' + opt.rot + 'deg);' : '') + '">' + text + '</span>';
  let e = LBL[key];
  if (!e) {
    e = LBL[key] = addLabel(inner, pos, { color: opt.color, bold: opt.bold, offset: opt.offset });
    LBLG[key] = CURG;
  } else {
    e.div.innerHTML = inner;
    e.pos.copy(pos);
    if (opt.offset) e.offset = opt.offset;
    if (opt.color) e.div.style.color = opt.color;
  }
  e.wu = opt.wu !== undefined ? opt.wu : (e.wu !== undefined ? e.wu : 0.42);
  e.maxW = opt.maxW !== undefined ? opt.maxW : e.maxW;
  e.tlen = plainLen(text);
  return e;
}
function fitFonts() {
  const H = canvas.clientHeight || 600;
  const ppu = H * (_labelZoomRef || 1) / (2 * d);
  Object.keys(LBL).forEach(k => {
    const e = LBL[k];
    let px = (e.wu || 0.42) * ppu;
    if (e.maxW) px = Math.min(px, (e.maxW * ppu) / (0.56 * Math.max(1, e.tlen)));
    px = Math.max(7, Math.min(40, px));
    e.div.style.fontSize = px.toFixed(1) + 'px';
  });
}
function setNetLabelsVisible(v) {
  Object.keys(LBL).forEach(k => {
    if (LBLG[k] === 'net') LBL[k].div.style.visibility = v ? '' : 'hidden';
  });
}

/* ── groups ──────────────────────────────────────────────────────────── */
const netGroup = new THREE.Group();
const insetGroup = new THREE.Group();
scene.add(netGroup); scene.add(insetGroup);

/* ── network layout / build ──────────────────────────────────────────── */
const STAGE = [
  { w: 0.55, h: 0.90, d: 0.90, dim: '56 × 56 × 256(64)', C: 256, tight: 0.10, sep: 0.42, gap: 2.55 },
  { w: 0.80, h: 0.55, d: 0.55, dim: '28 × 28 × 512(128)', C: 512, tight: 0.16, sep: 0.34, gap: 2.55 },
  { w: 1.30, h: 0.34, d: 0.34, dim: '14 × 14 × 1024(256)', C: 1024, tight: 0.16, sep: 0.30, gap: 1.30 },
  { w: 2.20, h: 0.20, d: 0.20, dim: '7 × 7 × 2048(512)', C: 2048, tight: 0.14, sep: 0.28, gap: 0.80 }
];
const COUNTS = { 12: [3, 2, 2, 2], 24: [4, 2, 3, 3], 36: [5, 3, 4, 4] };
const REPEATS = { 12: [12, 18], 24: [24, 36], 36: [36, 54] };

let netRight = 26;

function buildNetwork(depth) {
  CURG = 'net';
  clearGroup(netGroup);
  dropInteractives('net');
  const counts = COUNTS[depth] || COUNTS[24];
  const reps = REPEATS[depth] || REPEATS[24];

  /* input image (photo on the big +X parallelogram face) */
  const IW = 0.08, IH = 3.0, ID = 3.0;
  addSlab(netGroup, 0, 0, IW, IH, ID, { front: 0x2b1f15, top: 0x40301f, side: 0x241a12 }, CANDLE_TEX);
  netGroup.add(makeArrow(V(1.42, 4.34, 0), V(0.58, 3.62, 0), 0x000000, 0.16));
  lbl('dim0', '224 × 224 × 3', V(2.45, 4.92, 0), { rot: -33, wu: 0.44 });

  /* first conv (orange) */
  const OX = 0.42, OW = 0.50, OH = 1.60, OD = 1.60;
  addSlab(netGroup, OX, 0, OW, OH, OD, ORANGE);
  netGroup.add(makeArrow(V(2.55, 3.05, 0), V(1.16, 1.94, 0), 0x000000, 0.16));
  lbl('dim1', '112 × 112 × 64', V(3.58, 3.66, 0), { rot: -33, wu: 0.44 });

  /* stages */
  let x = OX + OW + 0.55;
  const stageStart = [], stageEnd = [];
  for (let si = 0; si < 4; si++) {
    const s = STAGE[si], n = counts[si];
    const xs = [];
    let cx = x;
    for (let i = 0; i < n; i++) {
      xs.push(cx);
      cx += s.w + (i === n - 2 ? s.sep : s.tight);
    }
    const endX = xs[n - 1] + s.w;
    stageStart.push(xs[0]); stageEnd.push(endX);

    xs.forEach((bx) => {
      const g = addSlab(netGroup, bx, 0, s.w, s.h, s.d, BLUE);
      g.userData.mesh.userData.grp = 'net';
      registerInteractive(g.userData.mesh, {
        title: 'Stage ' + (si + 1) + ' ResBlock — ' + s.dim,
        tooltip: 'ResBlock ' + s.dim + ' (click)',
        body: 'Output tensor ' + s.dim.replace(/\(.*\)/, '') + 'with bottleneck width ' + (s.C / 4) + '. ' +
          'Inside: Conv 1×1 squeezes ' + s.C + '→' + (s.C / 4) + ', Conv 3×3 works at ' + (s.C / 4) +
          ', Conv 1×1 expands ' + (s.C / 4) + '→' + s.C + ', then the identity skip is added at ⊕.',
        onClick: () => { setStageChannels(si); setMode('detail'); }
      });
    });

    /* bracket above the stage: solid — dotted ellipsis — solid, arrows down-left */
    const topScr = s.h + s.d * SZ;
    const by = topScr + 0.80;
    const bxA = xs[0] + s.w * 0.30;
    const bxB = endX + s.d * SZ + 0.55;
    const mid = (bxA + bxB) / 2, gh = Math.min(0.42, (bxB - bxA) * 0.18);
    netGroup.add(makeLine([V(bxA, by, 0), V(mid - gh, by, 0)]));
    netGroup.add(makeLine([V(mid + gh, by, 0), V(bxB, by, 0)]));
    for (let k = -1; k <= 1; k++) netGroup.add(makeDot(V(mid + k * gh * 0.62, by, 0.02), 0.038, 0x000000));
    xs.forEach(bx => {
      const startX = Math.min(bxB - 0.05, bx + s.w * 0.5 + s.d * SZ + 0.60);
      netGroup.add(makeArrow(V(startX, by, 0), V(bx + s.w * 0.5, s.h + 0.02, s.d * 0.5), 0x000000, 0.15));
    });
    const lx = si === 0 ? bxA + 1.05 : bxA + 0.90;
    const ly = si === 0 ? by + 1.00 : by + 0.95;
    lbl('st' + si, 'ResBlock<br>' + s.dim, V(lx, ly, 0), { rot: -33, wu: 0.44 });

    x = endX + s.gap;
  }

  /* two DISTINCT inter-stage repetition counters (24 / 36 at default depth) */
  [[0, 1, 'bt0', 0], [1, 2, 'bt1', 1]].forEach(t => {
    const gx = (stageEnd[t[0]] + stageStart[t[1]]) / 2;
    const nRep = reps[t[3]];
    lbl(t[2], nRep + ' blocks<br>total', V(gx, 0.72, 0),
      { wu: 0.42, color: '#2b5f83', align: 'center' });
    netGroup.add(makeDot(V(gx - 1.18, 0.30, 0.02), 0.052, 0x2b5f83));
    netGroup.add(makeDot(V(gx + 1.18, 0.30, 0.02), 0.052, 0x2b5f83));
  });

  /* logit bars */
  const bx0 = stageEnd[3] + 0.80, BW = 0.12, BD = 0.12, lowH = 0.52, gapH = 0.26, topH = 0.52;
  const BSEP = 0.85;
  [bx0, bx0 + BSEP].forEach((bx, i) => {
    addSlab(netGroup, bx, 0, BW, lowH, BD, TEAL);
    addSlab(netGroup, bx, lowH + gapH, BW, topH, BD, TEAL);
    for (let k = 0; k < 3; k++)
      netGroup.add(makeDot(V(bx + BW / 2, lowH + 0.07 + k * 0.065, BD / 2 + 0.01), 0.020, 0x333333));
    lbl('k1000' + i, '1000', V(bx + BW / 2 + (i ? 0.22 : -0.22), lowH + gapH + topH + 0.36, BD / 2),
      { wu: 0.40, align: 'center' });
  });

  /* bottom call-outs: arrows point up-right into their target block */
  function callout(key, text, tgt, ax, ay, lx2, ly2) {
    const tsx = tgt.x + SZ * tgt.z, tsy = tgt.y + SZ * tgt.z;
    netGroup.add(makeArrow(V(tsx + ax, tsy + ay, 0), tgt, 0x000000, 0.16));
    lbl(key, text, V(tsx + lx2, tsy + ly2, 0), { rot: -33, wu: 0.42 });
  }
