  callout('maxpool', 'MaxPool', V(stageStart[0], 0.05, STAGE[0].d / 2), -1.15, -1.40, -1.95, -2.10);
  for (let si = 1; si < 4; si++) {
    callout('sub' + si, 'Subsample', V(stageStart[si], 0.04, STAGE[si].d / 2), -1.35, -0.95, -2.45, -1.65);
