/* ── inset panel (local u,v units × IS, anchored upper-right) ────────── */
const IS = 1.18;
const IL = {
  PW: 15.30, PH: 2.45, boxH: 0.62, gap: 0.22,
  midV: 1.00, skipV: 1.92, cubeU: 0.95, eqU: 1.78, jU: 2.28, chainU: 2.58
