let IX0 = 8.0;
const IY0 = 4.70;
function IU(u) { return IX0 + u * IS; }
function IV(v) { return IY0 + v * IS; }

const CHAIN = [
  { t: 'BN', w: 0.70, c: COL.bn, k: 'bn' }, { t: 'ReLU', w: 0.95, c: COL.relu, k: 'relu' }, { t: 'Conv 1×1', w: 1.60, c: COL.white, k: 'c1' },
  { t: 'BN', w: 0.70, c: COL.bn, k: 'bn' }, { t: 'ReLU', w: 0.95, c: COL.relu, k: 'relu' }, { t: 'Conv 3×3', w: 1.60, c: COL.white, k: 'c3' },
  { t: 'BN', w: 0.70, c: COL.bn, k: 'bn' }, { t: 'ReLU', w: 0.95, c: COL.relu, k: 'relu' }, { t: 'Conv 1×1', w: 1.60, c: COL.white, k: 'c1b' }
];
const CINFO = {
  bn: ['Batch Normalization', 'Normalizes each channel over the mini-batch, then rescales with learned γ, β. Keeps activations well-conditioned so very deep stacks stay trainable.'],
  relu: ['ReLU', 'Element-wise max(0, x) — the non-linearity between convolutions.'],
  c1: ['Conv 1×1 (squeeze)', 'Bottleneck: drops the channel count from C to C/4 so the expensive 3×3 runs on a quarter of the channels.'],
  c3: ['Conv 3×3', 'The only spatial convolution in the block; it runs at the narrow bottleneck width C/4.'],
  c1b: ['Conv 1×1 (expand)', 'Restores the channel count back to C so the result can be added to the identity skip at ⊕.']
};

let chainBoxes = [], convCenters = [];
let opMesh = null, pulseMain = null, pulseSkip = null, pulseOut = null;
let OPU = 14.5;

/* ── flow path helpers ───────────────────────────────────────────────── */
function pathLen(pts) {
  let L = 0; const seg = [];
  for (let i = 1; i < pts.length; i++) { const dd = pts[i].distanceTo(pts[i - 1]); seg.push(dd); L += dd; }
  return { seg, L };
}
function pathAt(pts, info, t) {
  let dist = Math.max(0, Math.min(1, t)) * info.L;
  for (let i = 0; i < info.seg.length; i++) {
    if (dist <= info.seg[i] || i === info.seg.length - 1) {
      const f = info.seg[i] > 0 ? dist / info.seg[i] : 0;
      return pts[i].clone().lerp(pts[i + 1], Math.min(1, f));
    }
    dist -= info.seg[i];
  }
  return pts[pts.length - 1].clone();
}
let mainPts, skipPts, outPts, mainInfo, skipInfo, outInfo;

function buildInset() {
  CURG = 'inset';
  clearGroup(insetGroup);
  dropInteractives('inset');
  chainBoxes = []; convCenters = [];
  IX0 = Math.max(5.0, netRight - IL.PW * IS);

  const px0 = IU(0), py0 = IV(0), px1 = IU(IL.PW), py1 = IV(IL.PH);

  /* panel */
  const shp = roundedRectShape(px0, py0, px1, py1, 0.22);
  const fill = new THREE.Mesh(new THREE.ShapeGeometry(shp),
    new THREE.MeshBasicMaterial({ color: COL.panel, side: THREE.DoubleSide }));
  fill.position.z = -0.03; insetGroup.add(fill);
  const pp = shp.getPoints(64).map(p => V(p.x, p.y, -0.02));
  pp.push(pp[0].clone());
  insetGroup.add(makeLine(pp, 0x000000));

  /* cube + equals + entry arrow */
  const cube = makeSlab(0.44 * IS, 0.78 * IS, 0.78 * IS, BLUE);
  cube.position.set(IU(IL.cubeU), IV(IL.midV), 0);
  insetGroup.add(cube);
  cube.userData.mesh.userData.grp = 'inset';
  registerInteractive(cube.userData.mesh, {
    title: 'One ResBlock',
    tooltip: 'The block, abstracted',
    body: 'Every slab in the main diagram is one of these blocks. It equals the BN → ReLU → Conv chain on the right plus an identity skip summed at ⊕, so the layers only have to learn a residual correction.'
  });
  lbl('eq', '=', V(IU(IL.eqU), IV(IL.midV), 0.02),
    { wu: 0.80, color: '#2e8b80', bold: true, align: 'center' });
  insetGroup.add(makeArrow(V(IU(IL.eqU + 0.22), IV(IL.midV), 0.02), V(IU(IL.chainU), IV(IL.midV), 0.02), 0x000000, 0.16));
  insetGroup.add(makeDot(V(IU(IL.jU), IV(IL.midV), 0.03), 0.048, 0x000000));

  /* chain */
  let u = IL.chainU;
  CHAIN.forEach((it, i) => {
    const cu = u + it.w / 2;
    const b = flatBox(IU(cu), IV(IL.midV), it.w * IS, IL.boxH * IS, it.c);
    insetGroup.add(b);
    b.userData.mesh.userData.grp = 'inset';
    registerInteractive(b.userData.mesh, {
      title: CINFO[it.k][0], tooltip: it.t, body: CINFO[it.k][1]
    });
    chainBoxes.push({ mesh: b.userData.mesh, base: it.c, x0: IU(u), x1: IU(u + it.w), cx: IU(cu) });
    lbl('c' + i, it.t, V(IU(cu), IV(IL.midV), 0.03),
      { wu: 0.44, maxW: it.w * IS * 0.92, align: 'center' });
    if (it.t.indexOf('Conv') === 0) convCenters.push(IU(cu));
    if (i < CHAIN.length - 1)
      insetGroup.add(makeArrow(V(IU(u + it.w), IV(IL.midV), 0.02), V(IU(u + it.w + IL.gap), IV(IL.midV), 0.02), 0x000000, 0.15));
    u += it.w + IL.gap;
  });
  const chainEndU = u - IL.gap;
  OPU = chainEndU + 0.45;
  const OPR = 0.20 * IS;
  const opx = IU(OPU), opy = IV(IL.midV);
  insetGroup.add(makeArrow(V(IU(chainEndU), opy, 0.02), V(opx - OPR, opy, 0.02), 0x000000, 0.15));

  /* skip connection */
  insetGroup.add(makeLine([V(IU(IL.jU), opy, 0.02), V(IU(IL.jU), IV(IL.skipV), 0.02), V(opx, IV(IL.skipV), 0.02)]));
  insetGroup.add(makeArrow(V(opx, IV(IL.skipV), 0.02), V(opx, opy + OPR, 0.02), 0x000000, 0.16));

  /* circled plus */
  const circ = new THREE.Mesh(new THREE.CircleGeometry(OPR, 32),
    new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide }));
  circ.position.set(opx, opy, 0.01);
  insetGroup.add(circ);
  opMesh = circ;
  circ.userData.grp = 'inset';
  registerInteractive(circ, {
    title: '⊕ element-wise sum',
    tooltip: 'Residual addition',
    body: 'output = F(x) + x. Because the identity term passes straight through, gradients reach earlier layers unattenuated — the reason 50–150 layer networks train at all.'
  });
  const ring = [];
  for (let i = 0; i <= 48; i++) { const a = i / 48 * Math.PI * 2; ring.push(V(opx + OPR * Math.cos(a), opy + OPR * Math.sin(a), 0.02)); }
  insetGroup.add(makeLine(ring));
  insetGroup.add(makeLine([V(opx - OPR * 0.6, opy, 0.03), V(opx + OPR * 0.6, opy, 0.03)]));
  insetGroup.add(makeLine([V(opx, opy - OPR * 0.6, 0.03), V(opx, opy + OPR * 0.6, 0.03)]));

  /* output arrow leaving the panel */
  insetGroup.add(makeArrow(V(opx + OPR, opy, 0.02), V(IU(IL.PW - 0.25), opy, 0.02), 0x000000, 0.16));

  /* channel captions + titles */
  const capY = IV(IL.midV - 0.62);
  lbl('cap0', '', V(convCenters[0], capY, 0.03), { wu: 0.36, color: '#1d2f38', align: 'center' });
  lbl('cap1', '', V(convCenters[1], capY, 0.03), { wu: 0.36, color: '#1d2f38', align: 'center' });
  lbl('cap2', '', V(convCenters[2], capY, 0.03), { wu: 0.36, color: '#1d2f38', align: 'center' });
  lbl('itl', '', V(IU(1.15), IV(2.16), 0.03), { wu: 0.38, color: '#2c2c2c', align: 'center' });
  lbl('skl', 'identity skip', V((IU(IL.jU) + opx) / 2, IV(IL.skipV + 0.20), 0.03),
    { wu: 0.36, color: '#2b5f83', align: 'center' });

  /* pulses */
  const pr = 0.085 * IS;
  pulseMain = new THREE.Mesh(new THREE.SphereGeometry(pr, 14, 12), new THREE.MeshBasicMaterial({ color: 0xff6a00 }));
  pulseSkip = new THREE.Mesh(new THREE.SphereGeometry(pr, 14, 12), new THREE.MeshBasicMaterial({ color: 0x1f6fb5 }));
  pulseOut = new THREE.Mesh(new THREE.SphereGeometry(pr, 14, 12), new THREE.MeshBasicMaterial({ color: 0x2e8b57 }));
  [pulseMain, pulseSkip, pulseOut].forEach(p => { p.visible = false; p.position.z = 0.06; insetGroup.add(p); });

  mainPts = [V(IU(IL.jU), opy, 0.06), V(opx - OPR, opy, 0.06)];
  skipPts = [V(IU(IL.jU), opy, 0.06), V(IU(IL.jU), IV(IL.skipV), 0.06), V(opx, IV(IL.skipV), 0.06), V(opx, opy + OPR, 0.06)];
  outPts = [V(opx + OPR, opy, 0.06), V(IU(IL.PW - 0.25), opy, 0.06)];
  mainInfo = pathLen(mainPts); skipInfo = pathLen(skipPts); outInfo = pathLen(outPts);

  boundsPad(insetGroup, px0 - 0.15, py0 - 0.20, px1 + 0.15, py1 + 0.15);
}

/* ── stage channel captions ──────────────────────────────────────────── */
let curStage = 0;
function setStageChannels(si) {
  curStage = si;
  const C = STAGE[si].C, B = C / 4;
  const prev = CURG; CURG = 'inset';
  const capY = IV(IL.midV - 0.62);
  lbl('cap0', C + ' → ' + B, V(convCenters[0], capY, 0.03), {});
  lbl('cap1', B + ' → ' + B, V(convCenters[1], capY, 0.03), {});
  lbl('cap2', B + ' → ' + C, V(convCenters[2], capY, 0.03), {});
  lbl('itl', 'Stage ' + (si + 1) + ' · C = ' + C, V(IU(1.15), IV(2.16), 0.03), {});
  CURG = prev;
  document.getElementById('chanInfo').innerHTML =
    '<b>Stage ' + (si + 1) + ' bottleneck</b><br>Conv 1×1: ' + C + '→' + B +
    ' · Conv 3×3: ' + B + '→' + B + ' · Conv 1×1: ' + B + '→' + C;
  fitFonts();
}

/* ── build + camera ──────────────────────────────────────────────────── */
let depthVal = 24;
let mode = 'full';
buildNetwork(depthVal);
buildInset();
setStageChannels(0);

function frame() {
  setCameraView({
    projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0,
    heightFraction: mode === 'detail' ? 0.88 : 0.97
  });
  fitFonts();
}
frame();
document.getElementById('btnReset').style.display = '';

/* ── view mode ───────────────────────────────────────────────────────── */
function setMode(m) {
  mode = m;
  if (m === 'detail') {
    if (netGroup.parent) scene.remove(netGroup);
    setNetLabelsVisible(false);
  } else {
    if (!netGroup.parent) scene.add(netGroup);
    setNetLabelsVisible(true);
  }
  frame();
  document.getElementById('btnFull').classList.toggle('active', m === 'full');
  document.getElementById('btnDetail').classList.toggle('active', m === 'detail');
}
document.getElementById('btnFull').onclick = () => setMode('full');
document.getElementById('btnDetail').onclick = () => setMode('detail');

/* ── depth slider ────────────────────────────────────────────────────── */
const depthEl = document.getElementById('depth');
function setDepth(v) {
  depthVal = v;
  depthEl.value = String(v);
  document.getElementById('depthVal').textContent = v;
  const reps = REPEATS[v] || REPEATS[24];
  document.getElementById('r0').textContent = reps[0];
  document.getElementById('r1').textContent = reps[1];
  buildNetwork(v);
  buildInset();
  setStageChannels(curStage);
  flowReset();
  if (mode === 'full') { if (!netGroup.parent) scene.add(netGroup); setNetLabelsVisible(true); }
  else { setNetLabelsVisible(false); if (netGroup.parent) scene.remove(netGroup); }
  frame();
}
depthEl.addEventListener('input', () => setDepth(parseInt(depthEl.value, 10)));

/* ── signal-flow animation ───────────────────────────────────────────── */
let flowOn = false, flowT = 0, flowPhase = 0, opFlash = 0;
function highlight(px) {
  chainBoxes.forEach(b => {
    const on = flowOn && px >= b.x0 - 0.02 && px <= b.x1 + 0.02;
    const c = new THREE.Color(b.base);
    if (on) c.lerp(new THREE.Color(0xffe14d), 0.6);
    b.mesh.material.color.copy(c);
  });
}
function flowReset() {
  flowT = 0; flowPhase = 0; opFlash = 0;
  if (pulseMain) { pulseMain.visible = false; pulseSkip.visible = false; pulseOut.visible = false; }
  highlight(-999);
  if (opMesh) opMesh.material.color.set(0xffffff);
}
function flowTick(dt) {
  if (flowPhase === 0) {
    flowT += dt / 3.2;
    pulseMain.visible = true; pulseSkip.visible = true; pulseOut.visible = false;
    pulseMain.position.copy(pathAt(mainPts, mainInfo, flowT));
    pulseSkip.position.copy(pathAt(skipPts, skipInfo, flowT));
    highlight(pulseMain.position.x);
    if (flowT >= 1) { flowPhase = 1; flowT = 0; opFlash = 1; }
  } else if (flowPhase === 1) {
    opFlash -= dt / 0.45;
    const c = new THREE.Color(0xffffff).lerp(new THREE.Color(0xffd23f), Math.max(0, opFlash));
    opMesh.material.color.copy(c);
    pulseMain.visible = false; pulseSkip.visible = false;
    highlight(-999);
    if (opFlash <= 0) { flowPhase = 2; flowT = 0; opMesh.material.color.set(0xffffff); }
  } else {
    flowT += dt / 0.7;
    pulseOut.visible = true;
    pulseOut.position.copy(pathAt(outPts, outInfo, flowT));
    if (flowT >= 1) { pulseOut.visible = false; flowPhase = 0; flowT = 0; }
  }
}

let _lastT = performance.now(), _lastH = 0, _lastRef = 0;
(function loop() {
  requestAnimationFrame(loop);
  const n = performance.now();
  const dt = Math.min(0.05, (n - _lastT) / 1000); _lastT = n;
  if (flowOn) flowTick(dt);
  if (canvas.clientHeight !== _lastH || _labelZoomRef !== _lastRef) {
    _lastH = canvas.clientHeight; _lastRef = _labelZoomRef; fitFonts();
  }
})();

const btnFlow = document.getElementById('btnFlow');
btnFlow.onclick = () => {
  flowOn = !flowOn;
  if (flowOn) {
    if (mode !== 'detail') setMode('detail');
    flowReset(); flowOn = true;
    btnFlow.textContent = '■ Stop signal trace'; btnFlow.classList.add('active');
  } else {
    flowReset();
    btnFlow.textContent = '▶ Trace signal through ResBlock'; btnFlow.classList.remove('active');
  }
};

/* ── guided tour ─────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'Tensor pipeline', view: 'full', depth: 24, flow: false,
    text: 'Follow the tensors left to right: the 224×224×3 image becomes 112×112×64 after Conv 7×7 stride 2, then four residual stages shrink space and grow channels to 7×7×2048 before AvgPool + FC gives 1000 logits.'
  },
  {
    title: 'Depth is repetition', view: 'full', depth: 36, flow: false,
    text: 'Push the depth slider: the dotted ellipsis in each bracket means “repeat me”, and the two counters (24 and 36 blocks at the default) climb to 36 and 54 while every tensor dimension stays exactly the same.'
  },
  {
    title: 'Inside one block', view: 'detail', depth: 36, flow: false,
    text: 'Open the inset: the single cube expands into BN → ReLU → Conv 1×1 → BN → ReLU → Conv 3×3 → BN → ReLU → Conv 1×1, with a skip line arcing over the top.'
  },
  {
    title: 'Two paths, one sum', view: 'detail', depth: 24, flow: true,
    text: 'Play the signal trace: the main path is processed layer by layer while the identity copy runs unchanged along the skip; the ⊕ adds them, so gradients reach earlier layers directly.'
  }
];
let step = 0;
function goToStep(i) {
  step = (i + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  if (s.depth !== depthVal) setDepth(s.depth);
  setMode(s.view);
  flowOn = s.flow;
  flowReset(); flowOn = s.flow;
  btnFlow.textContent = flowOn ? '■ Stop signal trace' : '▶ Trace signal through ResBlock';
  btnFlow.classList.toggle('active', flowOn);
  document.getElementById('stepTitle').textContent = (step + 1) + '. ' + s.title;
  document.getElementById('stepText').textContent = s.text;
}
document.getElementById('btnNext').onclick = () => goToStep(step + 1);
document.getElementById('btnPrev').onclick = () => goToStep(step - 1);
goToStep(0);
// @FIGURE_CODE_END

